    // ============================================================
    // Incoming decrypt
    // ============================================================

    function createToggleInterface(originalEnc, decryptedText, parentEl) {
        parentEl.innerHTML = '';
        parentEl.dataset.vkdecOriginal = originalEnc;

        const textSpan = document.createElement('span');
        textSpan.className = 'vk-dec-content';
        textSpan.dataset.vkdecSkip = 'true';
        textSpan.textContent = decryptedText;
        textSpan.style.fontWeight = 'normal';

        const toggleLink = document.createElement('a');
        toggleLink.href = '#';
        toggleLink.className = 'vk-dec-toggle';
        toggleLink.dataset.vkdecSkip = 'true';
        toggleLink.textContent = '[шифр]';
        toggleLink.title = 'Показать зашифрованный оригинал';

        toggleLink.addEventListener('click', (e) => {
            e.preventDefault();
            e.stopPropagation();

            if (toggleLink.textContent === '[шифр]') {
                textSpan.textContent = originalEnc;
                textSpan.style.fontFamily = 'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace';
                toggleLink.textContent = '[текст]';
            } else {
                textSpan.textContent = decryptedText;
                textSpan.style.fontFamily = '';
                toggleLink.textContent = '[шифр]';
            }
        });

        parentEl.appendChild(textSpan);
        parentEl.appendChild(document.createTextNode(' '));
        parentEl.appendChild(toggleLink);

        parentEl.dataset.vkdecDone = 'true';
    }

    function createErrorInterface(originalEnc, errorText, parentEl) {
        parentEl.innerHTML = '';
        parentEl.dataset.vkdecOriginal = originalEnc;

        const rawSpan = document.createElement('span');
        rawSpan.className = 'vk-dec-content';
        rawSpan.dataset.vkdecSkip = 'true';
        rawSpan.textContent = originalEnc;

        const errorLine = document.createElement('span');
        errorLine.className = 'vk-dec-error';
        errorLine.dataset.vkdecSkip = 'true';
        errorLine.textContent = `ошибка: ${errorText}`;

        parentEl.appendChild(rawSpan);
        parentEl.appendChild(errorLine);
        parentEl.dataset.vkdecDone = 'true';
    }

    function createFragmentStatusInterface(parentEl, received, total, originalText) {
        parentEl.innerHTML = '';
        parentEl.dataset.vkdecOriginal = originalText;

        const status = document.createElement('span');
        status.className = 'vk-dec-fragment-status';
        status.dataset.vkdecSkip = 'true';
        status.textContent = `Получена часть зашифрованного сообщения: ${received} из ${total}`;
        parentEl.appendChild(status);
        parentEl.dataset.vkdecDone = 'true';
    }

    function formatByteSize(size) {
        const value = Number(size) || 0;
        if (value < 1024) return `${value} B`;
        if (value < 1024 * 1024) return `${(value / 1024).toFixed(1)} KB`;
        return `${(value / (1024 * 1024)).toFixed(1)} MB`;
    }

    function getMediaLinkName(link) {
        if (!link) return '';

        const headline = link.querySelector('.AttachmentCell__headline, h4');
        if (headline?.textContent) {
            return headline.textContent.trim();
        }

        return (link.textContent || '').trim();
    }

    function setMediaLinkName(link, name) {
        if (!link) return;

        const headline = link.querySelector('.AttachmentCell__headline, h4');
        if (headline) {
            headline.textContent = name;
            return;
        }

        link.textContent = name;
    }

    function setMediaLinkFootnote(link, metadata, sizeBytes) {
        if (!link) return;

        const footnote = link.querySelector('.AttachmentCell__footnote');
        if (!footnote) return;

        const ext = (String(metadata?.originalName || '').split('.').pop() || 'BIN').toUpperCase();
        footnote.textContent = `${ext} ᐧ ${formatByteSize(sizeBytes)}`;
    }

    function isEncryptedMediaLink(link) {
        const name = getMediaLinkName(link);
        const href = link.getAttribute('href') || '';
        const footnote = (link.querySelector('.AttachmentCell__footnote')?.textContent || '').trim();

        return (
            /\.vke$/i.test(name) ||
            /\.vke($|[?#])/i.test(href) ||
            (/\.vke/i.test(name) && /\bVKE\b/i.test(footnote))
        );
    }

    function getEncryptedMediaLinks() {
        const links = new Set();

        document.querySelectorAll('a[href]').forEach(link => {
            if (link.closest('.vk-p2p-media-box')) return;
            if (link.dataset.vkP2PMediaLink === 'true') {
                links.add(link);
                return;
            }

            if (!isEncryptedMediaLink(link)) return;

            const container = link.closest(
                'article, .ConvoMessage, .ConvoMessage__text, .MessageText, .im_msg_text, .im-message--text, [role="listitem"], .Attachments'
            );
            if (!container) return;

            links.add(link);
        });

        return links;
    }

    function ensureMediaInterface(link) {
        if (link.dataset.vkP2PMediaLink === 'true') {
            const existing = link.parentElement?.querySelector('.vk-p2p-media-box');
            if (existing) return existing;
        }

        if (!link.dataset.vkP2POriginalHref) {
            link.dataset.vkP2POriginalHref = link.getAttribute('href') || '';
            link.dataset.vkP2POriginalText = getMediaLinkName(link);
            link.dataset.vkP2POriginalFootnote = (link.querySelector('.AttachmentCell__footnote')?.textContent || '').trim();
        }

        const box = document.createElement('div');
        box.className = 'vk-p2p-media-box';
        box.dataset.vkdecSkip = 'true';

        const actions = document.createElement('div');
        actions.className = 'vk-p2p-media-actions';

        const decryptBtn = document.createElement('button');
        decryptBtn.type = 'button';
        decryptBtn.className = 'vk-p2p-media-btn';
        decryptBtn.textContent = '🔓 Расшифровать вложение';

        const downloadLink = document.createElement('a');
        downloadLink.className = 'vk-p2p-media-download';
        downloadLink.textContent = 'Скачать';
        downloadLink.hidden = true;
        downloadLink.target = '_blank';
        downloadLink.rel = 'noopener noreferrer';

        const meta = document.createElement('div');
        meta.className = 'vk-p2p-media-meta';
        meta.textContent = 'Зашифрованное вложение VKEncrypt';

        const preview = document.createElement('div');
        preview.className = 'vk-p2p-media-preview';

        const error = document.createElement('div');
        error.className = 'vk-p2p-media-error';

        actions.appendChild(decryptBtn);
        actions.appendChild(downloadLink);
        box.appendChild(actions);
        box.appendChild(meta);
        box.appendChild(preview);
        box.appendChild(error);

        decryptBtn.addEventListener('click', () => {
            decryptIncomingMediaLink(link, { manual: true });
        });

        link.insertAdjacentElement('afterend', box);
        link.dataset.vkP2PMediaLink = 'true';
        return box;
    }

    function restoreMediaLink(link) {
        if (!link) return;

        const originalHref = link.dataset.vkP2POriginalHref;
        const originalText = link.dataset.vkP2POriginalText;
        const originalFootnote = link.dataset.vkP2POriginalFootnote;

        if (typeof originalHref === 'string') {
            link.setAttribute('href', originalHref);
        }

        if (typeof originalText === 'string') {
            setMediaLinkName(link, originalText);
        }

        const footnote = link.querySelector('.AttachmentCell__footnote');
        if (footnote && typeof originalFootnote === 'string') {
            footnote.textContent = originalFootnote;
        }

        link.removeAttribute('download');
    }

    function getMediaCacheKey(link) {
        return link?.dataset?.vkP2POriginalHref || link?.getAttribute('href') || '';
    }

    function getCachedDecryptedMedia(link) {
        const key = getMediaCacheKey(link);
        return key ? MEDIA_DECRYPT_CACHE.get(key) || null : null;
    }

    function setCachedDecryptedMedia(link, value) {
        const key = getMediaCacheKey(link);
        if (!key) return;
        MEDIA_DECRYPT_CACHE.set(key, value);
    }

    function resetMediaInterface(box, options = {}) {
        if (!box) return;
        const { preserveAutoTried = false } = options;

        const link = box.previousElementSibling?.matches?.('a[href]')
            ? box.previousElementSibling
            : null;

        const preview = box.querySelector('.vk-p2p-media-preview');
        const error = box.querySelector('.vk-p2p-media-error');
        const downloadLink = box.querySelector('.vk-p2p-media-download');
        const decryptBtn = box.querySelector('.vk-p2p-media-btn');
        const meta = box.querySelector('.vk-p2p-media-meta');

        if (preview?.dataset.vkP2PObjectUrl) {
            delete preview.dataset.vkP2PObjectUrl;
        }

        if (preview) preview.innerHTML = '';
        if (error) error.textContent = '';
        if (downloadLink) {
            downloadLink.hidden = true;
            downloadLink.removeAttribute('href');
            downloadLink.removeAttribute('download');
        }
        if (decryptBtn) {
            decryptBtn.disabled = false;
            decryptBtn.hidden = false;
            decryptBtn.textContent = '🔓 Расшифровать вложение';
            decryptBtn.removeAttribute('title');
        }
        if (meta) {
            meta.textContent = 'Зашифрованное вложение VKEncrypt';
        }

        restoreMediaLink(link);

        delete box.dataset.vkP2PDecoded;
        delete box.dataset.vkP2PPlatformBlocked;
        if (!preserveAutoTried) {
            delete box.dataset.vkP2PAutoTried;
        }
    }

    function restoreAllIncomingMedia() {
        document.querySelectorAll('.vk-p2p-media-box').forEach(box => resetMediaInterface(box));
    }

    async function fetchEncryptedMediaBytes(link) {
        const url = link.href;

        if (typeof GM_xmlhttpRequest === 'function' && /^https?:/i.test(url) && !url.startsWith(location.origin)) {
            return new Promise((resolve, reject) => {
                GM_xmlhttpRequest({
                    method: 'GET',
                    url,
                    responseType: 'arraybuffer',
                    onload: (response) => {
                        if (response.status >= 200 && response.status < 300 && response.response) {
                            resolve(new Uint8Array(response.response));
                            return;
                        }

                        reject(new Error(`HTTP ${response.status}`));
                    },
                    onerror: () => {
                        reject(new Error('GM_xmlhttpRequest failed'));
                    }
                });
            });
        }

        const platformBlockReason = getCrossOriginMediaBlockReason(url);
        if (platformBlockReason) {
            throw new Error(platformBlockReason);
        }

        const response = await fetch(url, {
            credentials: 'include'
        });

        if (!response.ok) {
            throw new Error(`HTTP ${response.status}`);
        }

        return new Uint8Array(await response.arrayBuffer());
    }

    function renderDecryptedMedia(box, metadata, bytes, cachedObjectUrl = '') {
        const link = box.previousElementSibling?.matches?.('a[href]')
            ? box.previousElementSibling
            : null;
        const preview = box.querySelector('.vk-p2p-media-preview');
        const meta = box.querySelector('.vk-p2p-media-meta');
        const downloadLink = box.querySelector('.vk-p2p-media-download');
        const decryptBtn = box.querySelector('.vk-p2p-media-btn');
        const blob = new Blob([bytes], {
            type: metadata.mime || 'application/octet-stream'
        });
        const objectUrl = cachedObjectUrl || URL.createObjectURL(blob);

        if (preview?.dataset.vkP2PObjectUrl) {
            URL.revokeObjectURL(preview.dataset.vkP2PObjectUrl);
        }

        preview.innerHTML = '';
        preview.dataset.vkP2PObjectUrl = objectUrl;

        if (/^image\//i.test(metadata.mime || '')) {
            const img = document.createElement('img');
            img.src = objectUrl;
            img.alt = metadata.originalName || 'encrypted image';
            preview.appendChild(img);
        } else if (/^audio\//i.test(metadata.mime || '')) {
            const audio = document.createElement('audio');
            audio.controls = true;
            audio.src = objectUrl;
            preview.appendChild(audio);
        } else if (/^video\//i.test(metadata.mime || '')) {
            const video = document.createElement('video');
            video.controls = true;
            video.src = objectUrl;
            preview.appendChild(video);
        }

        if (meta) {
            meta.textContent = `${metadata.originalName || 'media'} • ${formatByteSize(metadata.originalSize || bytes.length)}`;
        }

        if (downloadLink) {
            downloadLink.href = objectUrl;
            downloadLink.download = metadata.originalName || 'media.bin';
            downloadLink.hidden = false;
        }

        if (link) {
            link.href = objectUrl;
            link.download = metadata.originalName || 'media.bin';
            setMediaLinkName(link, metadata.originalName || 'media.bin');
            setMediaLinkFootnote(link, metadata, metadata.originalSize || bytes.length);
        }

        if (decryptBtn) {
            decryptBtn.disabled = false;
            decryptBtn.hidden = true;
        }

        box.dataset.vkP2PDecoded = 'true';
    }

    async function decryptIncomingMediaLink(link, { manual = false } = {}) {
        const box = ensureMediaInterface(link);
        const decryptBtn = box.querySelector('.vk-p2p-media-btn');
        const error = box.querySelector('.vk-p2p-media-error');

        if (!hasAnyKeys()) {
            if (manual) showSeedSetupModal();
            return;
        }

        if (decryptBtn) {
            decryptBtn.disabled = true;
            decryptBtn.textContent = 'Расшифровываю...';
        }
        if (error) error.textContent = '';

        const platformBlockReason = getCrossOriginMediaBlockReason(link.href);
        if (platformBlockReason) {
            resetMediaInterface(box, { preserveAutoTried: !manual });
            applyMediaPlatformBlock(box, platformBlockReason);
            if (manual) {
                showToast(`⚠️ ${platformBlockReason}`);
            }
            return;
        }

        try {
            const cached = getCachedDecryptedMedia(link);
            if (cached) {
                renderDecryptedMedia(box, cached.metadata || {}, cached.bytes, cached.objectUrl || '');
            } else {
                const containerBytes = await fetchEncryptedMediaBytes(link);
                const parsed = parseEncryptedMediaContainer(containerBytes);
                const slotId = parsed.metadata?.keyId || currentKeySlot;
                const keyHex = getAllKeys()[slotId];

                if (!keyHex) {
                    throw new Error(`Ключ "${slotId}" не найден`);
                }

                const bytes = await decryptBinaryAESGCM(parsed.encryptedPayload, keyHex);
                const objectUrl = URL.createObjectURL(new Blob([bytes], {
                    type: parsed.metadata?.mime || 'application/octet-stream'
                }));

                setCachedDecryptedMedia(link, {
                    metadata: parsed.metadata || {},
                    bytes,
                    objectUrl
                });
                renderDecryptedMedia(box, parsed.metadata || {}, bytes, objectUrl);
            }
        } catch (err) {
            resetMediaInterface(box, { preserveAutoTried: !manual });
            if (error) {
                error.textContent = `ошибка: ${err.message}`;
            }
            if (manual) {
                showToast(`❌ Не удалось расшифровать вложение: ${err.message}`);
            }
        } finally {
            if (decryptBtn && box.dataset.vkP2PDecoded !== 'true') {
                decryptBtn.disabled = false;
            }
        }
    }

    function decorateIncomingMediaLinks() {
        getEncryptedMediaLinks().forEach(link => {
            const box = ensureMediaInterface(link);

            if (!settings.autoDecrypt) {
                if (!box.dataset.vkP2PDecoded) {
                    const btn = box.querySelector('.vk-p2p-media-btn');
                    if (btn) {
                        btn.hidden = false;
                        btn.textContent = '🔓 Расшифровать вложение';
                    }
                }
                return;
            }

            if (box.dataset.vkP2PAutoTried === 'true') return;
            observeMediaPreview(link, box);
        });
    }

    function observeMediaPreview(link, box) {
        if (!mediaPreviewObserver) {
            mediaPreviewObserver = new IntersectionObserver((entries) => {
                entries.forEach(entry => {
                    if (!entry.isIntersecting) return;

                    const targetBox = entry.target;
                    mediaPreviewObserver.unobserve(targetBox);

                    if (targetBox.dataset.vkP2PAutoTried === 'true') return;
                    targetBox.dataset.vkP2PAutoTried = 'true';

                    const targetLink = targetBox.previousElementSibling?.matches?.('a[href]')
                        ? targetBox.previousElementSibling
                        : null;
                    if (!targetLink) return;

                    decryptIncomingMediaLink(targetLink, { manual: false });
                });
            }, {
                root: null,
                rootMargin: '120px 0px',
                threshold: 0.01
            });
        }

        mediaPreviewObserver.observe(box);
    }

    function restoreIncomingMessage(msgEl) {
        const originalEnc = msgEl.dataset.vkdecOriginal;
        if (!originalEnc) return;

        msgEl.innerHTML = '';
        msgEl.textContent = originalEnc;
        delete msgEl.dataset.vkdecDone;
    }

    function restoreAllIncomingMessages() {
        document.querySelectorAll('[data-vkdec-original]').forEach(el => restoreIncomingMessage(el));
    }

    function extractNodeText(node) {
        if (!node) return '';

        if (node.nodeType === Node.TEXT_NODE) {
            return node.textContent || '';
        }

        if (node.nodeType !== Node.ELEMENT_NODE) {
            return '';
        }

        const el = /** @type {HTMLElement} */ (node);

        if (el.dataset?.vkdecSkip === 'true') {
            return '';
        }

        if (el.tagName === 'IMG') {
            return el.getAttribute('alt') || '';
        }

        let out = '';
        el.childNodes.forEach(child => {
            out += extractNodeText(child);
        });
        return out;
    }

    function extractMessageText(msgEl) {
        return extractNodeText(msgEl).trim();
    }

    async function processIncomingMessage(msgEl) {
        if (!settings.autoDecrypt) return;
        if (!hasAnyKeys()) return;
        if (msgEl.dataset.vkdecDone) return;

        const text = extractMessageText(msgEl);
        const parsed = parseEncryptedMessage(text);
        if (parsed) {
            const keyHex = getAllKeys()[parsed.keyId];
            if (!keyHex) return;

            try {
                const payload = decodePayloadForCodec(parsed.encodedPayload, parsed.codecId);
                const decrypted = await decryptAESGCM(payload, keyHex);
                createToggleInterface(parsed.originalText, decrypted, msgEl);
            } catch (err) {
                console.error('❌ Ошибка расшифровки:', err);
                createErrorInterface(parsed.originalText, err.message, msgEl);
            }
            return;
        }

        if (!isWordsDictionaryText(text)) return;

        for (const keyHex of Object.values(getAllKeys())) {
            try {
                const packet = await decryptWordMessage(text, keyHex);
                if (packet) {
                    await acceptWordFragment(packet, msgEl, text);
                    return;
                }
            } catch {
                // Обычный текст из словаря должен оставаться обычным текстом.
            }
        }
    }

    function getIncomingMessageElements() {
        const elements = new Set();

        document.querySelectorAll(
            '.ConvoMessage__text, .MessageText, .im_msg_text, .im-message--text'
        ).forEach(el => {
            if (el.closest('[data-vkdec-done="true"]')) return;
            elements.add(el);
        });

        document.querySelectorAll('[role="list"][aria-label*="Сообщения"]').forEach(list => {
            list.querySelectorAll('article span, article div').forEach(el => {
                if (el.dataset.vkdecSkip === 'true') return;
                if (el.closest('[data-vkdec-done="true"]')) return;
                if (el.children.length) return;

                const text = extractMessageText(el);
                if (parseEncryptedMessage(text) || isWordsDictionaryText(text)) {
                    elements.add(el);
                }
            });
        });

        return elements;
    }
    // ============================================================
    // Composer helpers
    // ============================================================

    function getComposerInput() {
        const selectors = [
            '.ComposerInput__input.ConvoComposer__input[contenteditable="true"]',
            '.ConvoComposer__input[contenteditable="true"]',
            '.im-editable[contenteditable="true"]',
            '[contenteditable="true"][role="textbox"]',
            '[contenteditable="true"]'
        ];

        for (const selector of selectors) {
            const list = Array.from(document.querySelectorAll(selector));
            const visible = list.find(el => {
                const rect = el.getBoundingClientRect();
                return rect.width > 20 && rect.height > 10;
            });

            if (visible) return visible;
        }

        return null;
    }

    function getComposerPanel(inputEl) {
        if (!inputEl) return null;

        const knownPanel = inputEl.closest(
            '.ConvoComposer__inputPanel, .ConvoComposer, .im-compose, .im-chat-input, form'
        );

        if (knownPanel) return knownPanel;

        let node = inputEl.parentElement;

        while (node && node !== document.body) {
            const rect = node.getBoundingClientRect();
            const hasComposerButtons = Boolean(node.querySelector(
                'button, [role="button"], [aria-label*="Загрузить файл"], [aria-label*="эмодзи"], [aria-label*="голосового"]'
            ));

            if (hasComposerButtons && rect.width > 80 && rect.height > 20) {
                return node;
            }

            node = node.parentElement;
        }

        return inputEl.parentElement;
    }

    function isComposerSubmitButton(button) {
        if (!button) return false;

        const className = String(button.className || '');
        if (/sendButton--submit|send-button--submit/.test(className)) return true;
        if (/sendButton--mic|send-button--mic/.test(className)) return false;

        if (button.querySelector(
            '.ConvoComposer__buttonIcon--submit, [class*="buttonIcon--submit"], [class*="icon--submit"]'
        )) {
            return true;
        }

        const label = `${button.getAttribute('aria-label') || ''} ${button.title || ''} ${button.textContent || ''}`.toLowerCase();
        return /отправить|send|submit/.test(label);
    }

    function findSendButton(panel) {
        const root = panel || document;

        const selectors = [
            'button[class*="sendButton--submit"]',
            '[class*="send-button--submit"]',
            '.ConvoComposer__buttonIcon--submit',
            'button[aria-label*="Отправить"]',
            '[aria-label*="Отправить"]',
            'button[type="submit"]',
            '.im-send-btn'
        ];

        for (const selector of selectors) {
            const found = root.querySelector(selector);
            if (!found) continue;

            const button = found.closest('button, [role="button"], a, div') || found;
            const rect = button.getBoundingClientRect();
            const label = `${button.getAttribute('aria-label') || ''} ${button.getAttribute('title') || ''}`.toLowerCase();

            if (/голос|микрофон|voice|record/.test(label) && !isComposerSubmitButton(button)) continue;

            if (rect.width > 0 && rect.height > 0) {
                return button;
            }
        }

        const icon = root.querySelector('svg.vkuiIcon--send_24, .vkuiIcon--send_24');
        if (icon) {
            const button = icon.closest('button, [role="button"], a, div') || icon;
            const label = `${button.getAttribute?.('aria-label') || ''} ${button.getAttribute?.('title') || ''}`.toLowerCase();
            if (!/голос|микрофон|voice|record/.test(label)) return button;
        }

        return null;
    }

    function waitForComposerClear(inputEl, previousText, timeoutMs = 1200) {
        const isAccepted = () => !inputEl?.isConnected || getInputPlainText(inputEl) !== previousText;

        if (!inputEl || isAccepted()) {
            return Promise.resolve(true);
        }

        return new Promise(resolve => {
            let settled = false;
            let observer;

            const finish = accepted => {
                if (settled) return;
                settled = true;
                observer?.disconnect();
                resolve(accepted);
            };

            observer = new MutationObserver(() => {
                if (isAccepted()) finish(true);
            });
            observer.observe(inputEl, {
                childList: true,
                subtree: true,
                characterData: true
            });

            if (isAccepted()) {
                finish(true);
                return;
            }

            setTimeout(() => finish(isAccepted()), timeoutMs);
        });
    }

    async function triggerComposerSend(inputEl, panel, { verify = false } = {}) {
        const previousText = getInputPlainText(inputEl);
        const sendBtn = findSendButton(panel);

        if (sendBtn) {
            sendBtn.click();
        } else if (inputEl) {
            inputEl.dispatchEvent(new KeyboardEvent('keydown', {
                key: 'Enter',
                code: 'Enter',
                keyCode: 13,
                which: 13,
                bubbles: true,
                cancelable: true
            }));
        } else {
            return false;
        }

        return verify ? waitForComposerClear(inputEl, previousText) : true;
    }

    function findComposerButton(panel, labels) {
        const root = panel || document;

        for (const label of labels) {
            const selector = [
                `button[aria-label*="${label}"]`,
                `[role="button"][aria-label*="${label}"]`,
                `[aria-label*="${label}"]`
            ].join(',');

            const found = root.querySelector(selector);
            if (!found) continue;

            const button = found.closest('button, [role="button"], a, div') || found;
            const rect = button.getBoundingClientRect();

            if (rect.width > 0 && rect.height > 0) {
                return button;
            }
        }

        return null;
    }

    function findUploadButton(panel) {
        return findComposerButton(panel, [
            'Загрузить файл',
            'Прикрепить',
            'прикрепить',
            'файл'
        ]);
    }

    function findEmojiButton(panel) {
        return findComposerButton(panel, [
            'эмодзи',
            'Эмодзи',
            'стикер',
            'Стикер'
        ]);
    }

    function getDirectChildWithin(parent, child) {
        if (!parent || !child || !parent.contains(child)) return null;

        let node = child;
        while (node.parentElement && node.parentElement !== parent) {
            node = node.parentElement;
        }

        return node.parentElement === parent ? node : null;
    }

    function insertAfterReference(node, reference) {
        if (!node || !reference?.parentNode) return false;
        reference.parentNode.insertBefore(node, reference.nextSibling);
        return true;
    }

    function insertBeforeReference(node, reference) {
        if (!node || !reference?.parentNode) return false;
        reference.parentNode.insertBefore(node, reference);
        return true;
    }

    function getComposerInsertReference(panel, inputEl) {
        if (!panel || !inputEl) return null;

        let node = inputEl;

        while (node.parentElement && node.parentElement !== panel) {
            node = node.parentElement;
        }

        return node.parentElement === panel ? node : inputEl;
    }

    function getInputPlainText(inputEl) {
        if (!inputEl) return '';

        if ('value' in inputEl) {
            return inputEl.value.trim();
        }

        return inputEl.innerText.trim();
    }

    function setInputPlainText(inputEl, text) {
        if (!inputEl) return;

        inputEl.focus();

        if ('value' in inputEl) {
            inputEl.value = text;
        } else {
            inputEl.innerText = text;

            const range = document.createRange();
            const sel = window.getSelection();

            range.selectNodeContents(inputEl);
            range.collapse(false);

            sel.removeAllRanges();
            sel.addRange(range);
        }

        inputEl.dispatchEvent(new InputEvent('input', {
            bubbles: true,
            inputType: 'insertText',
            data: text
        }));

        inputEl.dispatchEvent(new Event('change', { bubbles: true }));
    }

    function isComposerFileInput(inputEl) {
        if (!inputEl || inputEl.type !== 'file') return false;
        if (!getComposerInput()) return false;

        const accept = String(inputEl.accept || '').toLowerCase();
        return (
            accept.includes('image') ||
            accept.includes('audio') ||
            accept.includes('video') ||
            accept.includes('*/*') ||
            accept === ''
        );
    }

    async function handleMediaFileInputChange(event) {
        const inputEl = event.target;

        if (!(inputEl instanceof HTMLInputElement) || inputEl.type !== 'file') return;
        if (inputEl.dataset.vkP2PMediaSynthetic === 'true') {
            delete inputEl.dataset.vkP2PMediaSynthetic;
            return;
        }
        if (!settings.encryptMediaUploads) return;
        if (!isComposerFileInput(inputEl)) return;

        const files = Array.from(inputEl.files || []);
        if (!files.length) return;

        const hasMedia = files.some(file => isEncryptableMediaFile(file));
        if (!hasMedia) return;

        if (!hasAnyKeys()) {
            event.preventDefault();
            event.stopPropagation();
            event.stopImmediatePropagation?.();
            inputEl.value = '';
            showSeedSetupModal();
            return;
        }

        const keyHex = getCurrentKeyHex();
        if (!keyHex) {
            event.preventDefault();
            event.stopPropagation();
            event.stopImmediatePropagation?.();
            showToast(`❌ Ключ "${currentKeySlot}" не найден`);
            return;
        }

        event.preventDefault();
        event.stopPropagation();
        event.stopImmediatePropagation?.();

        try {
            const outputFiles = [];

            for (const file of files) {
                if (isEncryptableMediaFile(file)) {
                    outputFiles.push(await buildEncryptedMediaFile(file, keyHex, currentKeySlot));
                } else {
                    outputFiles.push(file);
                }
            }

            const dataTransfer = new DataTransfer();
            outputFiles.forEach(file => dataTransfer.items.add(file));
            inputEl.files = dataTransfer.files;
            inputEl.dataset.vkP2PMediaSynthetic = 'true';
            inputEl.dispatchEvent(new Event('change', { bubbles: true }));

            const mediaCount = outputFiles.filter(file => isEncryptedMediaName(file.name)).length;
            showToast(`✅ Зашифровал вложения до отправки: ${mediaCount}`);
        } catch (err) {
            inputEl.value = '';
            showToast(`❌ Не удалось зашифровать вложения: ${err.message}`);
        }
    }

    async function encryptCurrentInput({ showErrors = true } = {}) {
        if (!hasAnyKeys()) {
            showSeedSetupModal();
            return false;
        }

        const inputEl = getComposerInput();

        if (!inputEl) {
            if (showErrors) showToast('❌ Не нашёл поле ввода');
            return false;
        }

        const plainText = getInputPlainText(inputEl);

        if (!plainText) return false;

        if (parseEncryptedMessage(plainText)) {
            return true;
        }

        const keyHex = getCurrentKeyHex();

        if (!keyHex) {
            if (showErrors) showToast(`❌ Ключ "${currentKeySlot}" не найден`);
            return false;
        }

        try {
            const codecId = normalizeCodecId(settings.cipherCodec);

            if (codecId === 'words') {
                const messages = await encodePlaintextToWordMessages(plainText, keyHex);
                pendingWordMessages = messages.slice(1);
                pendingWordChatId = getCurrentChatId();
                setInputPlainText(inputEl, messages[0]);
                lastEncryptedAt = Date.now();
                if (messages.length > 1) {
                    showToast(`✅ Сообщение разбито на ${messages.length} частей`);
                }
                return true;
            }

            const b64 = await encryptAESGCM(plainText, keyHex);
            pendingWordMessages = [];
            pendingWordChatId = '';
            const payload = encodePayloadForCodec(b64, codecId);
            const encryptedMsg = formatEncryptedMessage(currentKeySlot, payload, codecId);

            setInputPlainText(inputEl, encryptedMsg);
            lastEncryptedAt = Date.now();

            return true;
        } catch (err) {
            console.error('❌ Ошибка шифрования:', err);
            if (showErrors) showToast('❌ Не удалось зашифровать: ' + err.message);
            return false;
        }
    }

    async function sendPendingWordMessages() {
        while (pendingWordMessages.length) {
            const inputEl = getComposerInput();
            const panel = getComposerPanel(inputEl);
            if (!inputEl) {
                showToast('⚠️ Не удалось отправить оставшиеся части');
                return;
            }

            if (pendingWordChatId && getCurrentChatId() !== pendingWordChatId) {
                pendingWordMessages = [];
                pendingWordChatId = '';
                showToast('⚠️ Отправка отменена: открыт другой чат');
                return;
            }

            const nextMessage = pendingWordMessages[0];
            setInputPlainText(inputEl, nextMessage);
            const accepted = await triggerComposerSend(inputEl, panel, { verify: true });
            if (!accepted) {
                showToast('⚠️ VK не подтвердил отправку части сообщения');
                return;
            }

            pendingWordMessages.shift();
            await new Promise(resolve => setTimeout(resolve, 220));
        }

        pendingWordChatId = '';
    }

    async function autoEncryptAndSend(event) {
        if (skipNextAutoEncrypt) return;
        if (!settings.autoEncrypt) return;
        if (isAutoSending) return;

        if (!hasAnyKeys()) {
            if (event) {
                event.preventDefault();
                event.stopPropagation();
                event.stopImmediatePropagation?.();
            }
            showSeedSetupModal();
            return;
        }

        const inputEl = getComposerInput();
        if (!inputEl) return;

        const plainText = getInputPlainText(inputEl);
        if (!plainText) return;

        if (parseEncryptedMessage(plainText)) {
            return;
        }

        if (event) {
            event.preventDefault();
            event.stopPropagation();
            event.stopImmediatePropagation?.();
        }

        const ok = await encryptCurrentInput({ showErrors: true });
        if (!ok) return;

        isAutoSending = true;

        setTimeout(async () => {
            try {
                const freshInput = getComposerInput();
                const panel = getComposerPanel(freshInput);

                if (freshInput) {
                    if (pendingWordChatId && getCurrentChatId() !== pendingWordChatId) {
                        pendingWordMessages = [];
                        pendingWordChatId = '';
                        showToast('⚠️ Отправка отменена: открыт другой чат');
                        return;
                    }

                    const accepted = await triggerComposerSend(freshInput, panel, { verify: true });
                    if (!accepted) {
                        showToast('⚠️ VK не подтвердил отправку зашифрованного сообщения');
                    } else if (pendingWordMessages.length) {
                        setTimeout(() => {
                            sendPendingWordMessages();
                        }, 260);
                    }
                } else {
                    showToast('⚠️ Зашифровал, но не нашёл кнопку отправки');
                }
            } finally {
                setTimeout(() => {
                    isAutoSending = false;
                }, 300);
            }
        }, 120);
    }

    function handleComposerKeydown(e) {
        if (skipNextAutoEncrypt) return;

        if (e.key === 'Enter' && !e.shiftKey && !e.ctrlKey && !e.altKey && !e.metaKey &&
            pendingWordMessages.length && !settings.autoEncrypt && !isAutoSending) {
            isAutoSending = true;
            setTimeout(() => {
                sendPendingWordMessages().finally(() => {
                    isAutoSending = false;
                });
            }, 260);
            return;
        }

        if (!settings.autoEncrypt) return;
        if (e.key !== 'Enter') return;

        // Shift+Enter оставляем для переноса строки.
        if (e.shiftKey || e.ctrlKey || e.altKey || e.metaKey) return;

        autoEncryptAndSend(e);
    }

    function attachEnterHandler(inputEl) {
        if (!inputEl || inputEl.dataset.vkP2PEnterAttached === 'true') return;

        inputEl.dataset.vkP2PEnterAttached = 'true';
        inputEl.addEventListener('keydown', handleComposerKeydown, true);
    }

    function attachSendButtonHandler(sendBtn) {
        if (!sendBtn || sendBtn.dataset.vkP2PSendAttached === 'true') return;

        sendBtn.dataset.vkP2PSendAttached = 'true';

        sendBtn.addEventListener('click', (e) => {
            if (pendingWordMessages.length && !settings.autoEncrypt && !isAutoSending) {
                e.preventDefault();
                e.stopPropagation();
                e.stopImmediatePropagation?.();
                isAutoSending = true;
                sendBtn.click();
                setTimeout(() => {
                    sendPendingWordMessages().finally(() => {
                        isAutoSending = false;
                    });
                }, 260);
                return;
            }

            if (skipNextAutoEncrypt) return;
            if (!settings.autoEncrypt) return;
            if (isAutoSending) return;

            const now = Date.now();

            // Если только что зашифровали вручную, не мешаем отправке.
            if (now - lastEncryptedAt < 250) return;

            autoEncryptAndSend(e);
        }, true);
    }
    // ============================================================
    // Protected voice recording
    // ============================================================

    let activeVoiceRecording = null;
    let voiceRecorderClickInstalled = false;

    function getVoiceRecorderButton(target) {
        const button = target?.closest?.('button, [role="button"]');
        if (!button) return null;
        if (button.dataset.vkP2PVoiceButton === 'true') return button;

        // VK can keep the microphone aria-label while reusing the same node for Send.
        // Structural submit markers must win over stale accessibility text.
        if (isComposerSubmitButton(button)) return null;

        const label = `${button.getAttribute('aria-label') || ''} ${button.title || ''}`;
        if (/(голосов(ое|ого|ую)|аудиосообщени|начать запись)/i.test(label)) return button;

        const isMicButton = button.matches(
            '.ConvoComposer__sendButton--mic, [class*="sendButton--mic"], [class*="send-button--mic"]'
        );
        if (!isMicButton) return null;

        return getInputPlainText(getComposerInput()) ? null : button;
    }

    function getVoiceRecorderMimeType() {
        const candidates = RUNTIME_PLATFORM.isSafari
            ? ['audio/mp4', 'audio/webm;codecs=opus', 'audio/webm', 'audio/ogg;codecs=opus']
            : ['audio/webm;codecs=opus', 'audio/ogg;codecs=opus', 'audio/webm', 'audio/mp4'];

        if (typeof MediaRecorder?.isTypeSupported !== 'function') {
            return '';
        }

        return candidates.find(type => MediaRecorder.isTypeSupported(type)) || '';
    }

    function getVoiceFileExtension(mimeType) {
        const mime = String(mimeType || '').toLowerCase();
        if (mime.includes('ogg')) return 'ogg';
        if (mime.includes('mp4') || mime.includes('aac')) return 'm4a';
        if (mime.includes('wav')) return 'wav';
        return 'webm';
    }

    function stopVoiceStream(stream) {
        stream?.getTracks?.().forEach(track => track.stop());
    }

    function findVoiceAttachmentInput(panel) {
        const inputs = Array.from(document.querySelectorAll('input[type="file"]'))
            .filter(input => !input.disabled && input.isConnected);
        if (!inputs.length) return null;

        const composerRoot = panel?.closest?.('.ConvoComposer, form, .im-compose, .im-chat-input') || panel;
        const score = input => {
            const accept = String(input.accept || '').toLowerCase();
            const hint = `${input.name || ''} ${input.id || ''} ${input.className || ''}`.toLowerCase();
            let value = 0;

            if (panel?.contains(input)) value += 20;
            if (composerRoot?.contains(input)) value += 10;
            if (!accept || accept.includes('*/*')) value += 8;
            if (accept.includes('application') || accept.includes('.vke')) value += 6;
            if (accept.includes('audio')) value += 3;
            if (/file|doc|attach|upload/.test(hint)) value += 4;
            if (accept.includes('image') && !accept.includes('audio') && !accept.includes('*')) value -= 8;

            return value;
        };

        return inputs.sort((left, right) => score(right) - score(left))[0] || null;
    }

    function attachEncryptedVoiceFile(panel, file) {
        const input = findVoiceAttachmentInput(panel);
        if (!input) {
            throw new Error('Не найден input вложений VK. Откройте меню «+» и повторите запись');
        }
        if (typeof DataTransfer !== 'function') {
            throw new Error('Платформа не поддерживает прикрепление записанного файла');
        }

        const dataTransfer = new DataTransfer();
        dataTransfer.items.add(file);
        input.files = dataTransfer.files;
        input.dataset.vkP2PMediaSynthetic = 'true';
        input.dispatchEvent(new Event('change', { bubbles: true }));
    }

    function createVoiceRecordingStatus(session) {
        const status = document.createElement('span');
        status.className = 'vk-p2p-voice-status';
        status.setAttribute('role', 'status');
        status.dataset.vkdecSkip = 'true';

        const reference = getDirectChildWithin(session.panel, session.button) || session.button;
        if (reference?.parentNode) {
            reference.parentNode.insertBefore(status, reference);
        } else {
            session.panel?.appendChild(status);
        }

        session.status = status;
        updateVoiceRecordingStatus(session);
    }

    function updateVoiceRecordingStatus(session) {
        if (!session.status) return;

        if (session.state === 'requesting') {
            session.status.textContent = 'Микрофон…';
            return;
        }
        if (session.state === 'encrypting') {
            session.status.textContent = 'Шифрую…';
            return;
        }

        const elapsed = Math.max(0, Math.floor((Date.now() - session.startedAt) / 1000));
        const minutes = String(Math.floor(elapsed / 60)).padStart(2, '0');
        const seconds = String(elapsed % 60).padStart(2, '0');
        session.status.textContent = `● ${minutes}:${seconds}`;
    }

    function markVoiceButtonRecording(session) {
        const button = session.button;
        session.originalAriaLabel = button.getAttribute('aria-label');
        session.originalTitle = button.getAttribute('title');
        button.dataset.vkP2PVoiceButton = 'true';
        button.classList.add('vk-p2p-voice-recording');
        button.setAttribute('aria-pressed', 'true');
        button.setAttribute('aria-label', 'Остановить и зашифровать голосовое сообщение');
        button.title = 'Остановить и прикрепить зашифрованную запись';
    }

    function restoreVoiceButton(session) {
        const button = session?.button;
        if (!button) return;

        button.classList.remove('vk-p2p-voice-recording');
        button.removeAttribute('aria-pressed');
        delete button.dataset.vkP2PVoiceButton;

        if (session.originalAriaLabel === null) button.removeAttribute('aria-label');
        else button.setAttribute('aria-label', session.originalAriaLabel);

        if (session.originalTitle === null) button.removeAttribute('title');
        else button.setAttribute('title', session.originalTitle);
    }

    function cleanupVoiceRecording(session) {
        if (!session) return;
        clearInterval(session.timer);
        stopVoiceStream(session.stream);
        session.status?.remove();
        restoreVoiceButton(session);
        if (activeVoiceRecording === session) activeVoiceRecording = null;
    }

    async function finishVoiceRecording(session) {
        if (session.finished) return;
        session.finished = true;

        if (session.cancelled) {
            cleanupVoiceRecording(session);
            return;
        }

        session.state = 'encrypting';
        updateVoiceRecordingStatus(session);

        try {
            const mimeType = session.recorder.mimeType || session.mimeType || 'audio/webm';
            const recording = new Blob(session.chunks, { type: mimeType });
            if (!recording.size) throw new Error('Запись получилась пустой');

            const extension = getVoiceFileExtension(mimeType);
            const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
            const sourceFile = new File(
                [recording],
                `voice-${timestamp}.${extension}`,
                { type: mimeType, lastModified: Date.now() }
            );
            const encryptedFile = await buildEncryptedMediaFile(
                sourceFile,
                session.keyHex,
                session.keySlot
            );

            attachEncryptedVoiceFile(session.panel, encryptedFile);
            showToast('✅ Голосовое зашифровано и прикреплено');
        } catch (err) {
            console.error('❌ Ошибка защищённой голосовой записи:', err);
            showToast(`❌ Не удалось прикрепить голосовое: ${err.message}`);
        } finally {
            cleanupVoiceRecording(session);
        }
    }

    async function startProtectedVoiceRecording(button) {
        if (!hasAnyKeys()) {
            showSeedSetupModal();
            return;
        }
        if (!navigator.mediaDevices?.getUserMedia || typeof MediaRecorder !== 'function') {
            showToast(`❌ ${getPlatformDisplayName()} не поддерживает запись через MediaRecorder`);
            return;
        }

        const keyHex = getCurrentKeyHex();
        if (!keyHex) {
            showToast(`❌ Ключ "${currentKeySlot}" не найден`);
            return;
        }

        const input = getComposerInput();
        const panel = getComposerPanel(input) || button.closest('form') || button.parentElement;
        const session = {
            button,
            panel,
            keyHex,
            keySlot: currentKeySlot,
            chunks: [],
            state: 'requesting',
            startedAt: Date.now(),
            finished: false,
            cancelled: false,
            stream: null,
            recorder: null,
            status: null,
            timer: null,
        };
        activeVoiceRecording = session;
        markVoiceButtonRecording(session);
        createVoiceRecordingStatus(session);

        try {
            const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            if (session.cancelled || activeVoiceRecording !== session) {
                stopVoiceStream(stream);
                return;
            }

            const mimeType = getVoiceRecorderMimeType();
            const recorder = mimeType
                ? new MediaRecorder(stream, { mimeType })
                : new MediaRecorder(stream);
            session.stream = stream;
            session.recorder = recorder;
            session.mimeType = mimeType;
            session.state = 'recording';
            session.startedAt = Date.now();

            recorder.addEventListener('dataavailable', event => {
                if (event.data?.size) session.chunks.push(event.data);
            });
            recorder.addEventListener('stop', () => finishVoiceRecording(session), { once: true });
            recorder.addEventListener('error', event => {
                const message = event.error?.message || 'MediaRecorder error';
                showToast(`❌ Ошибка записи: ${message}`);
                cleanupVoiceRecording(session);
            }, { once: true });
            recorder.start(250);
            session.timer = setInterval(() => updateVoiceRecordingStatus(session), 1000);
            updateVoiceRecordingStatus(session);
        } catch (err) {
            cleanupVoiceRecording(session);
            showToast(`❌ Не удалось начать запись: ${err.message}`);
        }
    }

    function stopProtectedVoiceRecording() {
        const session = activeVoiceRecording;
        if (!session) return;

        if (session.state === 'requesting') {
            session.cancelled = true;
            cleanupVoiceRecording(session);
            return;
        }
        if (session.state !== 'recording') return;

        session.state = 'encrypting';
        updateVoiceRecordingStatus(session);
        session.recorder.stop();
        stopVoiceStream(session.stream);
    }

    function cancelProtectedVoiceRecording() {
        const session = activeVoiceRecording;
        if (!session) return;

        session.cancelled = true;
        if (session.recorder?.state === 'recording') {
            session.recorder.onstop = null;
            session.recorder.stop();
        }
        cleanupVoiceRecording(session);
        showToast('⏸️ Голосовая запись отменена');
    }

    function handleProtectedVoiceClick(event) {
        const button = getVoiceRecorderButton(event.target);
        if (!button || !settings.encryptMediaUploads) return;

        event.preventDefault();
        event.stopPropagation();
        event.stopImmediatePropagation?.();

        if (activeVoiceRecording) {
            stopProtectedVoiceRecording();
            return;
        }

        startProtectedVoiceRecording(button);
    }

    function initProtectedVoiceRecorder() {
        if (voiceRecorderClickInstalled) return;
        voiceRecorderClickInstalled = true;
        document.addEventListener('click', handleProtectedVoiceClick, true);
    }

    function maintainProtectedVoiceRecorder() {
        if (activeVoiceRecording && !activeVoiceRecording.button.isConnected) {
            cancelProtectedVoiceRecording();
        }
    }
